def apply_all():
    manifest = json.loads((ROOT/'group_3.json').read_text())
    for entry in manifest['files']:
        rd=Path(entry['run_dir']); stem=rd.name
        if stem not in EDITS: continue
        original=(rd/'01_input.txt').read_text()
        edits=EDITS[stem]
        new=original
        for e in edits:
            assert new.count(e['before']) == 1, (stem,e['before'],new.count(e['before']))
            new=new.replace(e['before'],e['after'])
        eng=lambda s:Counter(re.findall(r"[A-Za-z]+(?:[-_’'][A-Za-z0-9]+)*",s))
        num=lambda s:Counter(re.findall(r'\d+(?:[.,]\d+)*',s))
        assert eng(original)==eng(new), (stem,eng(original)-eng(new),eng(new)-eng(original))
        assert num(original)==num(new), stem
        if entry['route']=='heavy':
            chunks=json.loads((rd/'chunk_manifest.json').read_text())['chunks']
            assigned=set()
            for c in chunks:
                text=original[c['start']:c['end']]
                for ix,e in enumerate(edits):
                    if e['before'] in text:
                        assert ix not in assigned
                        text=text.replace(e['before'],e['after'])
                        assigned.add(ix)
                if not c['passthrough']: (rd/c['rewritten_file']).write_text(text)
            assert len(assigned)==len(edits),(stem,'cross-chunk edit',len(assigned),len(edits))
        else:
            summary='\n<!-- HUMANIZE-SUMMARY -->\n<!-- 장르: 학부생용 기술 해설서. 경로: light. 영어 용어·수치·수식·코드·제목·링크 및 친근한 존댓말 보존. 자체검증: 6/6(교재 고유 표기 제외). 변경률: 공통 게이트 검증 대기. -->\n'
            (rd/'final.md').write_text(new.rstrip()+'\n'+summary)
        (rd/'edits.json').write_text(json.dumps({'edits':edits,'self_check':{'preserved_anchors':True,'genre':True,'register':True,'no_added_claims':True,'no_added_metaphors':True,'protected_tokens':True}},ensure_ascii=False,indent=2))
        print(stem,len(edits))

if __name__=='__main__': apply_all()
